package com.acme.core

import java.time.Clock
import java.time.Instant

class TokenCache(private val clock: Clock = Clock.systemUTC()) {
    private var token: String? = null
    private var expiresAt: Instant = Instant.EPOCH

    fun get(): String? = token?.takeIf { Instant.now(clock).isBefore(expiresAt) }

    fun put(value: String, ttlSeconds: Long) {
        token = value
        expiresAt = Instant.now(clock).plusSeconds(ttlSeconds)
    }
}

